func (this *BybitCore) CreateExpiredOptionMarket(symbol any) any {
	// support expired option contracts
	var quote any = nil
	var settle any = nil
	var optionParts []string = Split(symbol, "-")
	var symbolBase []string = Split(symbol, "/")
	var base any = nil
	var expiry any = nil
	if IsGreaterThan(GetIndexOf(symbol, "/"), OpNeg(1)) {
		base = this.SafeString(symbolBase, 0)
		expiry = this.SafeString(optionParts, 1)
		var symbolQuoteAndSettle *string = this.SafeString(symbolBase, 1)
		if symbolQuoteAndSettle == nil {
			panic(ExchangeError(Add(this.Id, " createExpiredOptionMarket() missing symbolQuoteAndSettle")))
		}
		var splitQuote []string = Split(symbolQuoteAndSettle, ":")
		var quoteAndSettle *string = this.SafeString(splitQuote, 0)
		quote = quoteAndSettle
		settle = quoteAndSettle
	} else {
		base = this.SafeString(optionParts, 0)
		expiry = this.ConvertMarketIdExpireDate(this.SafeString(optionParts, 1))
		if EndsWith(symbol, "-USDT") {
			quote = "USDT"
			settle = "USDT"
		} else {
			quote = "USDC"
			settle = "USDC"
		}
	}
	var strike *string = this.SafeString(optionParts, 2)
	var optionType *string = this.SafeString(optionParts, 3)
	var datetime any = this.ConvertExpireDate(expiry)
	var timestamp any = this.Parse8601(datetime)
	var amountPrecision any = nil
	var pricePrecision any = nil
	// hard coded amount and price precisions from fetchOptionMarkets
	if IsEqual(base, "BTC") {
		amountPrecision = this.ParseNumber("0.01")
		pricePrecision = this.ParseNumber("5")
	} else if IsEqual(base, "ETH") {
		amountPrecision = this.ParseNumber("0.1")
		pricePrecision = this.ParseNumber("0.1")
	} else if IsEqual(base, "SOL") {
		amountPrecision = this.ParseNumber("1")
		pricePrecision = this.ParseNumber("0.01")
	}
	var convertedExpireDate any = this.ConvertExpireDateToMarketIdDate(expiry)
	return map[string]any{
		"id":             Add(Add(Add(Add(Add(Add(base, "-"), convertedExpireDate), "-"), strike), "-"), optionType),
		"symbol":         Add(Add(Add(Add(Add(Add(Add(Add(Add(Add(base, "/"), quote), ":"), settle), "-"), expiry), "-"), strike), "-"), optionType),
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         base,
		"quoteId":        quote,
		"settleId":       settle,
		"active":         false,
		"type":           "option",
		"subType":        Ternary((IsEqual(base, settle)), "inverse", "linear"),
		"linear":         (!IsEqual(base, settle)),
		"inverse":        (IsEqual(base, settle)),
		"spot":           false,
		"swap":           false,
		"future":         false,
		"option":         true,
		"margin":         false,
		"contract":       true,
		"contractSize":   this.ParseNumber("1"),
		"expiry":         timestamp,
		"expiryDatetime": datetime,
		"optionType":     Ternary((optionType != nil && *optionType == "C"), "call", "put"),
		"strike":         this.ParseNumber(strike),
		"precision": map[string]any{
			"amount": amountPrecision,
			"price":  pricePrecision,
		},
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"info": nil,
	}
}
func (this *BybitCore) SafeMarket(optionalArgs ...any) any {
	marketId := GetArg(optionalArgs, 0, nil)
	_ = marketId
	market := GetArg(optionalArgs, 1, nil)
	_ = market
	delimiter := GetArg(optionalArgs, 2, nil)
	_ = delimiter
	marketType := GetArg(optionalArgs, 3, nil)
	_ = marketType
	var isOption bool = (!IsEqual(marketId, nil)) && ((IsGreaterThan(GetIndexOf(marketId, "-C"), OpNeg(1))) || (IsGreaterThan(GetIndexOf(marketId, "-P"), OpNeg(1))))
	if isOption && ((IsEqual(this.Markets_by_id, nil)) || !(InOp(this.Markets_by_id, marketId))) {
		// handle expired option contracts
		return this.CreateExpiredOptionMarket(marketId)
	}
	return this.Exchange.SafeMarket(marketId, market, delimiter, marketType)
}
func (this *BybitCore) GetBybitType(method any, market any, optionalArgs ...any) any {
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	var typeVar any = nil
	typeVarparamsVariable := this.HandleMarketTypeAndParams(method, market, params)
	typeVar = GetValue(typeVarparamsVariable, 0)
	params = GetValue(typeVarparamsVariable, 1)
	var subType any = nil
	subTypeparamsVariable := this.HandleSubTypeAndParams(method, market, params)
	subType = GetValue(subTypeparamsVariable, 0)
	params = GetValue(subTypeparamsVariable, 1)
	if (typeVar == "option") || (typeVar == "spot") {
		return []any{typeVar, params}
	}
	return []any{subType, params}
}
func (this *BybitCore) GetAmount(symbol any, amount any) any {
	// some markets like options might not have the precision available
	// and we shouldn't crash in those cases
	var market any = this.Market(symbol)
	var emptyPrecisionAmount bool = (IsEqual(GetValue(GetValue(market, "precision"), "amount"), nil))
	var amountString any = this.NumberToString(amount)
	if !emptyPrecisionAmount && (!IsEqual(amountString, "0")) {
		return this.AmountToPrecision(symbol, amount)
	}
	return amountString
}
func (this *BybitCore) GetPrice(symbol any, price any) any {
	if IsEqual(price, nil) {
		return price
	}
	var market any = this.Market(symbol)
	var emptyPrecisionPrice bool = (IsEqual(GetValue(GetValue(market, "precision"), "price"), nil))
	if !emptyPrecisionPrice {
		return this.PriceToPrecision(symbol, price)
	}
	return price
}
func (this *BybitCore) GetCost(symbol any, cost any) any {
	var market any = this.Market(symbol)
	var emptyPrecisionPrice bool = (IsEqual(GetValue(GetValue(market, "precision"), "price"), nil))
	if !emptyPrecisionPrice {
		return this.CostToPrecision(symbol, cost)
	}
	return cost
}

/**
 * @method
 * @name bybit#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://bybit-exchange.github.io/docs/v5/system-status
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure](https://docs.ccxt.com/#/?id=exchange-status-structure)
 */
func (this *BybitCore) FetchStatus(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *BybitCore) fetchStatusBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetV5SystemStatus(params))
	PanicOnError(response)
	//
	//     {
	//         "retCode": 0,
	//         "retMsg": "OK",
	//         "result": {
	//             "list": [
	//                 {
	//                     "id": "f9d6842d-5331-11f0-8fd3-c241b123dd9e",
	//                     "title": "t01",
	//                     "state": "completed",
	//                     "begin": "1751012688000",
	//                     "end": "1751012760000",
	//                     "href": "",
	//                     "serviceTypes": [ 1, 2, 3, 4, 5 ],
	//                     "product": [ 1, 2, 3, 4 ],
	//                     "uidSuffix": [],
	//                     "maintainType": 3,
	//                     "env": 2
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1751858399649
	//     }
	//
	var result any = this.SafeDict(response, "result", map[string]any{})
	var list any = this.SafeList(result, "list", []any{})
	var status string = "ok"
	var eta any = nil
	var url any = nil
	for i := 0; IsLessThan(i, GetArrayLength(list)); i++ {
		var event any = GetValue(list, i)
		var state *string = this.SafeString(event, "state")
		if state != nil && *state == "ongoing" {
			status = "maintenance"
			eta = this.SafeInteger(event, "end")
			url = this.SafeString(event, "href")
			break
		} else if state != nil && *state == "scheduled" {
			eta = this.SafeInteger(event, "begin")
			url = this.SafeString(event, "href")
		}
	}

	ch <- map[string]any{
		"status":  status,
		"updated": nil,
		"eta":     eta,
		"url":     url,
		"info":    response,
	}
	return nil
}

