func (this *BybitCore) ParseTicker(ticker any, optionalArgs ...any) any {
	//
	// spot
	//
	//     {
	//         "symbol": "BTCUSDT",
	//         "bid1Price": "20517.96",
	//         "bid1Size": "2",
	//         "ask1Price": "20527.77",
	//         "ask1Size": "1.862172",
	//         "lastPrice": "20533.13",
	//         "prevPrice24h": "20393.48",
	//         "price24hPcnt": "0.0068",
	//         "highPrice24h": "21128.12",
	//         "lowPrice24h": "20318.89",
	//         "turnover24h": "243765620.65899866",
	//         "volume24h": "11801.27771",
	//         "usdIndexPrice": "20784.12009279"
	//     }
	//
	// linear/inverse
	//
	//     {
	//         "symbol": "BTCUSD",
	//         "lastPrice": "16597.00",
	//         "indexPrice": "16598.54",
	//         "markPrice": "16596.00",
	//         "prevPrice24h": "16464.50",
	//         "price24hPcnt": "0.008047",
	//         "highPrice24h": "30912.50",
	//         "lowPrice24h": "15700.00",
	//         "prevPrice1h": "16595.50",
	//         "openInterest": "373504107",
	//         "openInterestValue": "22505.67",
	//         "turnover24h": "2352.94950046",
	//         "volume24h": "49337318",
	//         "fundingRate": "-0.001034",
	//         "nextFundingTime": "1672387200000",
	//         "predictedDeliveryPrice": "",
	//         "basisRate": "",
	//         "deliveryFeeRate": "",
	//         "deliveryTime": "0",
	//         "ask1Size": "1",
	//         "bid1Price": "16596.00",
	//         "ask1Price": "16597.50",
	//         "bid1Size": "1"
	//     }
	//
	// option
	//
	//     {
	//         "symbol": "BTC-30DEC22-18000-C",
	//         "bid1Price": "0",
	//         "bid1Size": "0",
	//         "bid1Iv": "0",
	//         "ask1Price": "435",
	//         "ask1Size": "0.66",
	//         "ask1Iv": "5",
	//         "lastPrice": "435",
	//         "highPrice24h": "435",
	//         "lowPrice24h": "165",
	//         "markPrice": "0.00000009",
	//         "indexPrice": "16600.55",
	//         "markIv": "0.7567",
	//         "underlyingPrice": "16590.42",
	//         "openInterest": "6.3",
	//         "turnover24h": "2482.73",
	//         "volume24h": "0.15",
	//         "totalVolume": "99",
	//         "totalTurnover": "1967653",
	//         "delta": "0.00000001",
	//         "gamma": "0.00000001",
	//         "vega": "0.00000004",
	//         "theta": "-0.00000152",
	//         "predictedDeliveryPrice": "0",
	//         "change24h": "86"
	//     }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var isSpot bool = (this.SafeString(ticker, "openInterestValue") == nil)
	var timestamp *int64 = this.SafeInteger(ticker, "time")
	var marketId *string = this.SafeString(ticker, "symbol")
	var typeVar any = Ternary(isSpot, "spot", "contract")
	market = this.SafeMarket(marketId, market, nil, typeVar)
	var symbol any = this.SafeSymbol(marketId, market, nil, typeVar)
	var last *string = this.SafeString(ticker, "lastPrice")
	var open *string = this.SafeString(ticker, "prevPrice24h")
	var percentage *string = this.SafeString(ticker, "price24hPcnt")
	percentage = Precise.StringMul(percentage, "100")
	var quoteVolume *string = this.SafeString(ticker, "turnover24h")
	var baseVolume *string = this.SafeString(ticker, "volume24h")
	var bid *string = this.SafeString(ticker, "bid1Price")
	var ask *string = this.SafeString(ticker, "ask1Price")
	var high *string = this.SafeString(ticker, "highPrice24h")
	var low *string = this.SafeString(ticker, "lowPrice24h")
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          high,
		"low":           low,
		"bid":           bid,
		"bidVolume":     this.SafeString2(ticker, "bidSize", "bid1Size"),
		"ask":           ask,
		"askVolume":     this.SafeString2(ticker, "askSize", "ask1Size"),
		"vwap":          nil,
		"open":          open,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        nil,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    baseVolume,
		"quoteVolume":   quoteVolume,
		"markPrice":     this.SafeString(ticker, "markPrice"),
		"indexPrice":    this.SafeString(ticker, "indexPrice"),
		"info":          ticker,
	}, market)
}

