	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1672376496682
	//     }
	//
	var result any = this.SafeDict(response, "result", map[string]any{})
	var tickerList any = this.SafeList(result, "list", []any{})

	ch <- this.ParseTickers(tickerList, parsedSymbols)
