	//         "isMaker": true,
	//         "execFee": "0.0000025",
	//         "execId": "2210000000101610464",
	//         "execQty": "0.01",
	//         "nextPageCursor": "267951%3A0%2C38567%3A0"
	//     },
	//
	// private USDC settled trades
	//
	//     {
	//         "symbol": "ETHPERP",
	//         "orderLinkId": "",
	//         "side": "Buy",
	//         "orderId": "aad0ee44-ce12-4112-aeee-b7829f6c3a26",
	//         "execFee": "0.0210",
	//         "feeRate": "0.000600",
