func (this *BybitCore) fetchTradesBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	since := GetArg(optionalArgs, 0, nil)
	_ = since
	limit := GetArg(optionalArgs, 1, nil)
	_ = limit
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	if IsEqual(symbol, nil) {
		panic(ArgumentsRequired(Add(this.Id, " fetchTrades() requires a symbol argument")))
	}
	if IsEqual(this.Markets, nil) {

		retRes337212 := (<-this.LoadMarkets())
		PanicOnError(retRes337212)
	}
	var market any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": GetValue(market, "id"),
	}
	if !IsEqual(limit, nil) {
		// spot: [1,60], default: 60.
		// others: [1,1000], default: 500
		AddElementToObject(request, "limit", limit)
	}
	var typeVar any = nil
	typeVarparamsVariable := this.GetBybitType("fetchTrades", market, params)
	typeVar = GetValue(typeVarparamsVariable, 0)
	params = GetValue(typeVarparamsVariable, 1)
	AddElementToObject(request, "category", typeVar)

	response := (<-this.PublicGetV5MarketRecentTrade(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "retCode": 0,
	//         "retMsg": "OK",
	//         "result": {
	//             "category": "spot",
	//             "list": [
	//                 {
	//                     "execId": "2100000000007764263",
	//                     "symbol": "BTCUSDT",
	//                     "price": "16618.49",
	//                     "size": "0.00012",
	//                     "side": "Buy",
	//                     "time": "1672052955758",
	//                     "isBlockTrade": false
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1672053054358
	//     }
	//
	var result any = this.SafeDict(response, "result", map[string]any{})
	var trades any = this.SafeList(result, "list", []any{})

	ch <- this.ParseTrades(trades, market, since, limit)
	return nil
}

/**
 * @method
 * @name bybit#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://bybit-exchange.github.io/docs/v5/market/orderbook
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *BybitCore) FetchOrderBook(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *BybitCore) fetchOrderBookBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	limit := GetArg(optionalArgs, 0, nil)
	_ = limit
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	if IsEqual(symbol, nil) {
		panic(ArgumentsRequired(Add(this.Id, " fetchOrderBook() requires a symbol argument")))
	}
	if IsEqual(this.Markets, nil) {

		retRes343112 := (<-this.LoadMarkets())
		PanicOnError(retRes343112)
	}
	var market any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": GetValue(market, "id"),
	}
	var defaultLimit any = 25
	if IsEqual(GetValue(market, "spot"), true) {
		// limit: [1, 50]. Default: 1
		defaultLimit = 50
		AddElementToObject(request, "category", "spot")
	} else {
		if IsEqual(GetValue(market, "option"), true) {
			// limit: [1, 25]. Default: 1
			AddElementToObject(request, "category", "option")
		} else if IsEqual(GetValue(market, "linear"), true) {
			// limit: [1, 500]. Default: 25
			AddElementToObject(request, "category", "linear")
		} else if IsEqual(GetValue(market, "inverse"), true) {
			// limit: [1, 500]. Default: 25
			AddElementToObject(request, "category", "inverse")
		}
	}
	AddElementToObject(request, "limit", Ternary((!IsEqual(limit, nil)), limit, defaultLimit))

	response := (<-this.PublicGetV5MarketOrderbook(this.Extend(request, params)))
	PanicOnError(response)
	//
	//     {
	//         "retCode": 0,
	//         "retMsg": "OK",
	//         "result": {
	//             "s": "BTCUSDT",
	//             "a": [
	//                 [
	//                     "16638.64",
	//                     "0.008479"
	//                 ]
	//             ],
	//             "b": [
	//                 [
	//                     "16638.27",
	//                     "0.305749"
	//                 ]
	//             ],
	//             "ts": 1672765737733,
	//             "u": 5277055
	//         },
	//         "retExtInfo": {},
	//         "time": 1672765737734
	//     }
	//
	var result any = this.SafeDict(response, "result", map[string]any{})
	var timestamp *int64 = this.SafeInteger(result, "ts")

	ch <- this.ParseOrderBook(result, symbol, timestamp, "b", "a")
	return nil
}
func (this *BybitCore) ParseBalance(response any) any {
	//
	// cross
	//     {
	//         "retCode": 0,
	//         "retMsg": "success",
	//         "result": {
	//             "acctBalanceSum": "0.122995614474732872",
	//             "debtBalanceSum": "0.011734191124529754",
	//             "loanAccountList": [
	//                 {
	//                     "free": "0.001143855",
	//                     "interest": "0",
	//                     "loan": "0",
	//                     "locked": "0",
	//                     "tokenId": "BTC",
	//                     "total": "0.001143855"
	//                 },
	//                 {
	//                     "free": "200.00005568",
	//                     "interest": "0.0008391",
	//                     "loan": "200",
	//                     "locked": "0",
	//                     "tokenId": "USDT",
	//                     "total": "200.00005568"
	//                 },
	//             ],
	//             "riskRate": "0.0954",
	//             "status": 1
	//         },
	//         "retExtInfo": {},
	//         "time": 1669843584123
	//     }
	//
	// funding
	//     {
	//         "retCode": 0,
	//         "retMsg": "success",
	//         "result": {
	//             "memberId": "533285",
	//             "accountType": "FUND",
	//             "balance": [
	//                 {
	//                     "coin": "USDT",
	//                     "transferBalance": "1010",
	//                     "walletBalance": "1010",
	//                     "bonus": ""
	//                 },
	//                 {
	//                     "coin": "USDC",
	//                     "transferBalance": "0",
	//                     "walletBalance": "0",
	//                     "bonus": ""
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1675865290069
	//     }
	//
	//  spot & swap
	//     {
	//         "retCode": 0,
	//         "retMsg": "OK",
	//         "result": {
	//             "list": [
	//                 {
	//                     "totalEquity": "18070.32797922",
	//                     "accountIMRate": "0.0101",
	//                     "totalMarginBalance": "18070.32797922",
	//                     "totalInitialMargin": "182.60183684",
	//                     "accountType": "UNIFIED",
	//                     "totalAvailableBalance": "17887.72614237",
	//                     "accountMMRate": "0",
	//                     "totalPerpUPL": "-0.11001349",
	//                     "totalWalletBalance": "18070.43799271",
	//                     "accountLTV": "0.017",
	//                     "totalMaintenanceMargin": "0.38106773",
	//                     "coin": [
	//                         {
	//                             "availableToBorrow": "2.5",
	//                             "bonus": "0",
	//                             "accruedInterest": "0",
	//                             "availableToWithdraw": "0.805994",
	//                             "totalOrderIM": "0",
	//                             "equity": "0.805994",
	//                             "totalPositionMM": "0",
	//                             "usdValue": "12920.95352538",
	//                             "unrealisedPnl": "0",
	//                             "borrowAmount": "0",
	//                             "totalPositionIM": "0",
	//                             "walletBalance": "0.805994",
	//                             "cumRealisedPnl": "0",
	//                             "coin": "BTC"
	//                         }
	//                     ]
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1672125441042
	//     }
	//
	var timestamp *int64 = this.SafeInteger(response, "time")
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
	var responseResult any = this.SafeDict(response, "result", map[string]any{})
	var currencyList any = this.SafeListN(responseResult, []any{"loanAccountList", "list", "balance"})
	if IsEqual(currencyList, nil) {
		// usdc wallet
		var code string = "USDC"
		var account any = this.Account()
		AddElementToObject(account, "free", this.SafeString(responseResult, "availableBalance"))
		AddElementToObject(account, "total", this.SafeString(responseResult, "walletBalance"))
		AddElementToObject(result, code, account)
	} else {
		for i := 0; IsLessThan(i, GetArrayLength(currencyList)); i++ {
			var entry any = GetValue(currencyList, i)
			var accountType *string = this.SafeString(entry, "accountType")
			if (accountType != nil && *accountType == "UNIFIED") || (accountType != nil && *accountType == "CONTRACT") || (accountType != nil && *accountType == "SPOT") {
				var coins any = this.SafeList(entry, "coin", []any{})
				for j := 0; IsLessThan(j, GetArrayLength(coins)); j++ {
					var account any = this.Account()
					var coinEntry any = GetValue(coins, j)
					var loan *string = this.SafeString(coinEntry, "borrowAmount")
					var interest *string = this.SafeString(coinEntry, "accruedInterest")
					if (loan != nil) && (interest != nil) {
						AddElementToObject(account, "debt", Precise.StringAdd(loan, interest))
					}
					AddElementToObject(account, "total", this.SafeString(coinEntry, "walletBalance"))
					var free *string = this.SafeString2(coinEntry, "availableToWithdraw", "free")
					if free != nil {
						AddElementToObject(account, "free", free)
					} else {
						var locked *string = this.SafeString(coinEntry, "locked", "0")
						var totalPositionIm *string = this.SafeString(coinEntry, "totalPositionIM", "0")
						var totalOrderIm *string = this.SafeString(coinEntry, "totalOrderIM", "0")
						var totalUsed *string = Precise.StringAdd(locked, totalPositionIm)
						totalUsed = Precise.StringAdd(totalUsed, totalOrderIm)
						AddElementToObject(account, "used", totalUsed)
					}
					// account['used'] = this.safeString (coinEntry, 'locked');
					var currencyId *string = this.SafeString(coinEntry, "coin")
					var code any = this.SafeCurrencyCode(currencyId)
					if !IsEqual(code, nil) {
						AddElementToObject(result, code, account)
					}
				}
			} else {
				var account any = this.Account()
				var loan *string = this.SafeString(entry, "loan")
				var interest *string = this.SafeString(entry, "interest")
				if (loan != nil) && (interest != nil) {
					AddElementToObject(account, "debt", Precise.StringAdd(loan, interest))
				}
				AddElementToObject(account, "total", this.SafeString2(entry, "total", "walletBalance"))
				AddElementToObject(account, "free", this.SafeStringN(entry, []any{"free", "availableBalanceWithoutConvert", "availableBalance", "transferBalance"}))
				AddElementToObject(account, "used", this.SafeString(entry, "locked"))
				var currencyId *string = this.SafeStringN(entry, []any{"tokenId", "coin", "currencyCoin"})
				var code any = this.SafeCurrencyCode(currencyId)
				if !IsEqual(code, nil) {
					AddElementToObject(result, code, account)
				}
			}
		}
	}
	return this.SafeBalance(result)
}

/**
 * @method
 * @name bybit#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://bybit-exchange.github.io/docs/v5/spot-margin-normal/account-info
 * @see https://bybit-exchange.github.io/docs/v5/asset/all-balance
 * @see https://bybit-exchange.github.io/docs/v5/account/wallet-balance
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.type] wallet type, ['spot', 'swap', 'funding']
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *BybitCore) FetchBalance(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *BybitCore) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params
	if IsEqual(this.Markets, nil) {

		retRes367112 := (<-this.LoadMarkets())
		PanicOnError(retRes367112)
	}
	var request map[string]any = map[string]any{}
	enableUnifiedMarginenableUnifiedAccountVariable := (<-this.IsUnifiedEnabled())
	enableUnifiedMargin := GetValue(enableUnifiedMarginenableUnifiedAccountVariable, 0)
	enableUnifiedAccount := GetValue(enableUnifiedMarginenableUnifiedAccountVariable, 1)
	var isUnifiedAccount bool = (IsEqual(enableUnifiedMargin, true)) || (IsEqual(enableUnifiedAccount, true))
	var typeVar any = nil
	// don't use getBybitType here
	typeVarparamsVariable := this.HandleMarketTypeAndParams("fetchBalance", nil, params)
	typeVar = GetValue(typeVarparamsVariable, 0)
	params = GetValue(typeVarparamsVariable, 1)
	var subType any = nil
	subTypeparamsVariable := this.HandleSubTypeAndParams("fetchBalance", nil, params)
	subType = GetValue(subTypeparamsVariable, 0)
	params = GetValue(subTypeparamsVariable, 1)
	if (typeVar == "swap") || (typeVar == "future") {
		typeVar = subType
	}
	var lowercaseRawType any = Ternary((!IsEqual(typeVar, nil)), ToLower(typeVar), nil)
	var isSpot bool = (IsEqual(typeVar, "spot"))
	var isLinear bool = (IsEqual(typeVar, "linear"))
	var isInverse bool = (IsEqual(typeVar, "inverse"))
	var isFunding bool = (IsEqual(lowercaseRawType, "fund")) || (IsEqual(lowercaseRawType, "funding"))
	if isUnifiedAccount {
		var unifiedMarginStatus *int64 = this.SafeInteger(this.Options, "unifiedMarginStatus", 6)
		if IsLessThan(unifiedMarginStatus, 5) {
			// it's not uta.20 where inverse are unified
			if isInverse {
				typeVar = "contract"
			} else {
				typeVar = "unified"
			}
		} else {
			typeVar = "unified" // uta.20 where inverse are unified
		}
	} else {
		if isLinear || isInverse {
			typeVar = "contract"
		}
	}
	var accountTypes any = this.SafeDict(this.Options, "accountsByType", map[string]any{})
	var unifiedType *string = this.SafeStringUpper(accountTypes, typeVar, typeVar)
	var marginMode any = nil
	marginModeparamsVariable := this.HandleMarginModeAndParams("fetchBalance", params)
	marginMode = GetValue(marginModeparamsVariable, 0)
	params = GetValue(marginModeparamsVariable, 1)
	var response any = nil
	if isSpot && (!IsEqual(marginMode, nil)) {

		response = (<-this.PrivateGetV5SpotCrossMarginTradeAccount(this.Extend(request, params)))
		PanicOnError(response)
	} else if isFunding {
		// use this endpoint only we have no other choice
		// because it requires transfer permission
		AddElementToObject(request, "accountType", "FUND")

		response = (<-this.PrivateGetV5AssetTransferQueryAccountCoinsBalance(this.Extend(request, params)))
		PanicOnError(response)
	} else {
		AddElementToObject(request, "accountType", unifiedType)

		response = (<-this.PrivateGetV5AccountWalletBalance(this.Extend(request, params)))
		PanicOnError(response)
	}

	//
	// cross
	//     {
	//         "retCode": 0,
	//         "retMsg": "success",
	//         "result": {
	//             "acctBalanceSum": "0.122995614474732872",
	//             "debtBalanceSum": "0.011734191124529754",
	//             "loanAccountList": [
	//                 {
	//                     "free": "0.001143855",
	//                     "interest": "0",
	//                     "loan": "0",
	//                     "locked": "0",
	//                     "tokenId": "BTC",
	//                     "total": "0.001143855"
	//                 },
	//                 {
	//                     "free": "200.00005568",
	//                     "interest": "0.0008391",
	//                     "loan": "200",
	//                     "locked": "0",
	//                     "tokenId": "USDT",
	//                     "total": "200.00005568"
	//                 },
	//             ],
	//             "riskRate": "0.0954",
	//             "status": 1
	//         },
	//         "retExtInfo": {},
	//         "time": 1669843584123
	//     }
	//
	// funding
	//     {
	//         "retCode": 0,
	//         "retMsg": "success",
	//         "result": {
	//             "memberId": "533285",
	//             "accountType": "FUND",
	//             "balance": [
	//                 {
	//                     "coin": "USDT",
	//                     "transferBalance": "1010",
	//                     "walletBalance": "1010",
	//                     "bonus": ""
	//                 },
	//                 {
	//                     "coin": "USDC",
	//                     "transferBalance": "0",
	//                     "walletBalance": "0",
	//                     "bonus": ""
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1675865290069
	//     }
	//
	//  spot & swap
	//     {
	//         "retCode": 0,
	//         "retMsg": "OK",
	//         "result": {
	//             "list": [
	//                 {
	//                     "totalEquity": "18070.32797922",
	//                     "accountIMRate": "0.0101",
	//                     "totalMarginBalance": "18070.32797922",
	//                     "totalInitialMargin": "182.60183684",
	//                     "accountType": "UNIFIED",
	//                     "totalAvailableBalance": "17887.72614237",
	//                     "accountMMRate": "0",
	//                     "totalPerpUPL": "-0.11001349",
	//                     "totalWalletBalance": "18070.43799271",
	//                     "accountLTV": "0.017",
	//                     "totalMaintenanceMargin": "0.38106773",
	//                     "coin": [
	//                         {
	//                             "availableToBorrow": "2.5",
	//                             "bonus": "0",
	//                             "accruedInterest": "0",
	//                             "availableToWithdraw": "0.805994",
	//                             "totalOrderIM": "0",
	//                             "equity": "0.805994",
	//                             "totalPositionMM": "0",
	//                             "usdValue": "12920.95352538",
	//                             "unrealisedPnl": "0",
	//                             "borrowAmount": "0",
	//                             "totalPositionIM": "0",
	//                             "walletBalance": "0.805994",
	//                             "cumRealisedPnl": "0",
	//                             "coin": "BTC"
	//                         }
	//                     ]
	//                 }
	//             ]
	//         },
	//         "retExtInfo": {},
	//         "time": 1672125441042
	//     }
	//
	ch <- this.ParseBalance(response)
	return nil
}
func (this *BybitCore) ParseOrderStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"NEW":                        "open",
		"PARTIALLY_FILLED":           "open",
		"FILLED":                     "closed",
		"CANCELED":                   "canceled",
		"PENDING_CANCEL":             "open",
		"PENDING_NEW":                "open",
		"REJECTED":                   "rejected",
		"PARTIALLY_FILLED_CANCELLED": "closed",
		"Created":                    "open",
		"New":                        "open",
		"Rejected":                   "rejected",
		"PartiallyFilled":            "open",
		"PartiallyFilledCanceled":    "closed",
		"Filled":                     "closed",
		"PendingCancel":              "open",
		"Cancelled":                  "canceled",
		"Untriggered":                "open",
		"Deactivated":                "canceled",
		"Triggered":                  "open",
		"Active":                     "open",
	}
	return this.SafeString(statuses, status, status)
}
func (this *BybitCore) ParseTimeInForce(timeInForce any) any {
	var timeInForces map[string]any = map[string]any{
		"GoodTillCancel":    "GTC",
		"ImmediateOrCancel": "IOC",
		"FillOrKill":        "FOK",
		"PostOnly":          "PO",
	}
	return this.SafeString(timeInForces, timeInForce, timeInForce)
}
