func (this *BybitCore) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	//     {
	//         "id": 234467,
	//         "user_id": 1,
	//         "coin": "BTC",
	//         "wallet_id": 27913,
	//         "type": "Realized P&L",
	//         "amount": "-0.00000006",
	//         "tx_id": "",
	//         "address": "BTCUSD",
	//         "wallet_balance": "0.03000330",
	//         "exec_time": "2019-12-09T00:00:25.000Z",
	//         "cross_seq": 0
	//     }
	//
	//     {
	//         "symbol": "XRPUSDT",
	//         "side": "Buy",
	//         "funding": "",
	//         "orderLinkId": "linear-order",
	//         "orderId": "592b7e41-78fd-42e2-9aa3-91e1835ef3e1",
	//         "fee": "0.00260280",
	//         "change": "-0.0026028",
	//         "cashFlow": "0",
	//         "transactionTime": "1672121182224",
	//         "type": "TRADE",
	//         "feeRate": "0.0006",
	//         "size": "12",
	//         "qty": "12",
	//         "cashBalance": "5086.58101322",
	//         "currency": "USDT",
	//         "category": "linear",
	//         "tradePrice": "0.3615",
	//         "tradeId": "8569c10f-5061-5891-81c4-a54929847eb3"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString2(item, "coin", "currency")
	var code any = this.SafeCurrencyCode(currencyId, currency)
	currency = this.SafeCurrency(currencyId, currency)
	var amountString *string = this.SafeString2(item, "amount", "change")
	var afterString *string = this.SafeString2(item, "wallet_balance", "cashBalance")
	var direction any = Ternary(Precise.StringLt(amountString, "0"), "out", "in")
	var before any = nil
	var after any = nil
	var amount any = nil
	if (afterString != nil) && (amountString != nil) {
		var difference any = Ternary((direction == "out"), amountString, Precise.StringNeg(amountString))
		before = this.ParseToNumeric(Precise.StringAdd(afterString, difference))
		after = this.ParseToNumeric(afterString)
		amount = this.ParseToNumeric(Precise.StringAbs(amountString))
	}
	var timestamp any = this.Parse8601(this.SafeString(item, "exec_time"))
	if IsEqual(timestamp, nil) {
		timestamp = this.SafeInteger(item, "transactionTime")
	}
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "id"),
		"direction":        direction,
		"account":          this.SafeString(item, "wallet_id"),
		"referenceId":      this.SafeString(item, "tx_id"),
		"referenceAccount": nil,
		"type":             this.ParseLedgerEntryType(this.SafeString(item, "type")),
		"currency":         code,
		"amount":           amount,
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           before,
		"after":            after,
		"status":           "ok",
		"fee": map[string]any{
			"currency": code,
			"cost":     this.SafeNumber(item, "fee"),
		},
	}, currency)
}
